        this.connection = DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
        initializeDatabase();
    }

    private void initializeDatabase() throws SQLException {
        String createTableSQL = "CREATE TABLE IF NOT EXISTS users (" +
                "id INT AUTO_INCREMENT PRIMARY KEY, " +
                "name VARCHAR(100) NOT NULL, " +
                "email VARCHAR(100) NOT NULL UNIQUE, " +
                "password_hash VARCHAR(255) NOT NULL, " +
                "salt VARCHAR(255) NOT NULL, " +
                "created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP" +
                ")";
        try (Statement stmt = connection.createStatement()) {
            stmt.execute(createTableSQL);
        }
    }

    public boolean registerUser(String name, String email, String password) {
        if (name == null || name.trim().isEmpty()) {
            return false;
        }
        if (email == null || !isValidEmail(email)) {
            return false;
        }
        if (password == null || password.length() < 6) {
            return false;
        }
        if (emailExists(email)) {
            return false;
        }
        try {
            String salt = generateSalt();
            String hashedPassword = hashPassword(password, salt);
            String insertSQL = "INSERT INTO users (name, email, password_hash, salt) VALUES (?, ?, ?, ?)";
            try (PreparedStatement pstmt = connection.prepareStatement(insertSQL)) {
                pstmt.setString(1, name.trim());
                pstmt.setString(2, email.toLowerCase().trim());
                pstmt.setString(3, hashedPassword);
                pstmt.setString(4, salt);
                return pstmt.executeUpdate() > 0;
            }
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }

    public boolean authenticateUser(String email, String password) {
        if (email == null || password == null) {
            return false;
        }
        String selectSQL = "SELECT password_hash, salt FROM users WHERE email = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(selectSQL)) {
            pstmt.setString(1, email.toLowerCase().trim());
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("password_hash");
                    String salt = rs.getString("salt");
                    String inputHash = hashPassword(password, salt);
                    return storedHash.equals(inputHash);
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return false;
    }

    private boolean emailExists(String email) {
        String checkSQL = "SELECT COUNT(*) FROM users WHERE email = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(checkSQL)) {
            pstmt.setString(1, email.toLowerCase().trim());
            try (ResultSet rs = pstmt.executeQuery()) {
                return rs.next() && rs.getInt(1) > 0;
            }
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }

    private boolean isValidEmail(String email) {
        return email != null && email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
    }

    private String generateSalt() {
        SecureRandom random = new SecureRandom();
        byte[] salt = new byte[16];
        random.nextBytes(salt);
        return Base64.getEncoder().encodeToString(salt);
    }

    private String hashPassword(String password, String salt) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(Base64.getDecoder().decode(salt));
            byte[] hashedPassword = md.digest(password.getBytes());
            return Base64.getEncoder().encodeToString(hashedPassword);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Error hashing password", e);
        }
    }

    public void close() {
        try {
            if (connection != null && !connection.isClosed()) {
                connection.close();
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        try {
            UserRegistrationSystem system = new UserRegistrationSystem();
            boolean result1 = system.registerUser("John Doe", "john@example.com", "password123");
            System.out.println("Registration result: " + result1);
            boolean result2 = system.registerUser("Jane Smith", "jane@example.com", "securepass456");
            System.out.println("Registration result: " + result2);
            boolean authResult = system.authenticateUser("john@example.com", "password123");
            System.out.println("Authentication result: " + authResult);
            system.close();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
